char* encrypt(const char* message, int key) {
    int len = strlen(message);
    char* encrypted = (char*)malloc((len + 1) * sizeof(char));
    for (int i = 0; i < len; i++) {
        if (message[i] >= 'A' && message[i] <= 'Z') {
            encrypted[i] = ENCRYPT(message[i], key);
        } else {
            encrypted[i] = message[i];
        }
    }
    encrypted[len] = '\0';
    return encrypted;
}

